/* ===================================================================
 * 会话管理
 *
 * 每次开始播放/被动预处理都会自增 immersiveSoundSessionCounter 并记为
 * activeImmersiveSoundSessionId。异步流程沿途用 isImmersiveSoundSessionInactive()
 * 检查自己的 sessionId 是否仍有效，失效就中止 —— 用于避免旧流程在用户
 * 触发新一轮播放后继续写入。
 *
 * 关于「停止后恢复播放」：
 * 原先 stopAllAudio + 自增计数器会作废 engine 持有的 playbackSessionId，
 * 于是再次点播放时 resume -> playList 的 isSessionActive(旧id) 返回 false
 * 而被 abort，音频无法 start。
 * 这里不再靠外部 hook 打补丁，而是显式记录「被停止的 session」并放行它：
 * stop 时把该 id 记入 resumedSessionId，isImmersiveSoundSessionActive 对
 * 这个 id 返回 true，使同一轮的 resume 可以继续。
 * =================================================================== */

var nativeConsoleLog = console.log;

/** 当前正在播放的 marker（karaoke marker 或 sequential engine） */
var marker;

/** 会话计数器与当前活动会话 id */
var immersiveSoundSessionCounter = 0;
var activeImmersiveSoundSessionId = 0;

/**
 * 被「停止」操作显式放行的 session id。
 * 停止旧会话后，引擎仍持有该 id 并会在 resume 时用 isSessionActive() 校验；
 * 放行它可让「停止 -> 点播放」恢复到同一轮播放，而不是被 abort。
 */
var resumedSessionId = null;

/**
 * 开始一次新的播放会话（会停止上一轮音频）。
 * @returns {number} 新会话 id
 */
function beginImmersiveSoundSession() {
    activeImmersiveSoundSessionId = ++immersiveSoundSessionCounter;
    resumedSessionId = null;
    stopAllAudio(window.marker || marker);
    window.marker = null;
    return activeImmersiveSoundSessionId;
}

/**
 * 开始一次「被动」会话：只做预处理，不打断当前正在播放的音频。
 * @returns {number} 新会话 id
 */
function beginPassiveImmersiveSoundSession() {
    activeImmersiveSoundSessionId = ++immersiveSoundSessionCounter;
    return activeImmersiveSoundSessionId;
}

/**
 * 取消当前播放会话（双击停止 / 关闭播放器）。
 * 记录被停止的会话 id 以便之后 resume 不被 abort。
 * @returns {number} 新会话 id
 */
function cancelImmersiveSoundSession() {
    // 放行「刚被停止的这一轮」，使随后点播放按钮能 resume 而不是被 abort
    const stoppedMarker = window.marker || marker;
    if (stoppedMarker && stoppedMarker.options && stoppedMarker.options.playbackSessionId != null) {
        resumedSessionId = stoppedMarker.options.playbackSessionId;
    } else if (Number.isFinite(activeImmersiveSoundSessionId)) {
        resumedSessionId = activeImmersiveSoundSessionId;
    }

    activeImmersiveSoundSessionId = ++immersiveSoundSessionCounter;
    stopAllAudio(stoppedMarker);
    window.marker = null;
    return activeImmersiveSoundSessionId;
}

/**
 * 判断某个 sessionId 是否仍然有效。
 * @param {number} sessionId
 * @returns {boolean}
 */
function isImmersiveSoundSessionActive(sessionId) {
    if (!Number.isFinite(sessionId)) return true;
    // 被停止但允许 resume 的那一轮视为有效
    if (resumedSessionId !== null && sessionId === resumedSessionId) return true;
    return sessionId === activeImmersiveSoundSessionId;
}

/**
 * 反向判断，并在失效时打印日志。
 * @param {number} sessionId
 * @param {string} stage 用于日志的阶段名
 * @returns {boolean}
 */
function isImmersiveSoundSessionInactive(sessionId, stage) {
    if (isImmersiveSoundSessionActive(sessionId)) return false;
    nativeConsoleLog(
        '[Immersive Sound] 会话已失效，停止后续流程: ' + stage
        + ' (session=' + sessionId + ', active=' + activeImmersiveSoundSessionId + ')'
    );
    return true;
}

window.cancelImmersiveSoundSession = cancelImmersiveSoundSession;
